40	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
41	
42	export interface ScenarioResult {
43	  results: StepResult[];
44	}
45	
46	const PROCESSING_FEE = 5;
47	
48	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	};
56	
57	const ALIKE_ITEMS_PER_BLOCK = 3;
58	const BLOCK_BASE_PREMIUM = 60;
59	const CURSE_SURCHARGE_RATE = 0.5;
60	const HIGH_ENCHANTMENT_LEVEL = 5;
61	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
62	const LOYALTY_YEARS_THRESHOLD = 2;
63	const LOYALTY_DISCOUNT_RATE = 0.2;
64	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
65	
66	const sum = (amounts: number[]): number =>
67	  amounts.reduce((total, amount) => total + amount, 0);
68	
69	const groupByType = (items: Item[]): Item[][] => {
70	  const itemsByType = new Map<string, Item[]>();
71	
72	  for (const item of items) {
73	    const alikeItems = itemsByType.get(item.type);
74	    if (alikeItems) alikeItems.push(item);
75	    else itemsByType.set(item.type, [item]);
76	  }
77	
78	  return [...itemsByType.values()];
79	};
80	
81	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];
82	
83	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
84	  alikeItems.length === ALIKE_ITEMS_PER_BLOCK
85	    ? BLOCK_BASE_PREMIUM
86	    : sum(alikeItems.map(basePremiumOf));
87	
88	const curseSurchargeOf = (item: Item): number =>
89	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
90	
91	const highEnchantmentSurchargeOf = (item: Item): number =>
92	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
93	    ? basePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
94	    : 0;
95	
96	const surchargesOf = (item: Item): number =>
97	  curseSurchargeOf(item) + highEnchantmentSurchargeOf(item);
98	
99	const loyaltyDiscountOf = (customer: Customer, basePremium: number): number =>
100	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
101	
102	const quote = ({ items }: QuoteStep, customer: Customer): StepResult => {
103	  const basePremium = sum(groupByType(items).map(basePremiumOfAlikeItems));
104	  const surcharges = sum(items.map(surchargesOf));
105	  const loyaltyDiscount = loyaltyDiscountOf(customer, basePremium);
106	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
107	
108	  return {
109	    premium:
110	      basePremium + surcharges - loyaltyDiscount + firstInsuranceSurcharge + PROCESSING_FEE,
111	  };
112	};
113	
114	export const runScenario = (scenario: Scenario): ScenarioResult => ({
115	  results: [quote(scenario.steps[0] as QuoteStep, scenario.customer)],
116	});
